insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('mae_motores_preparacion', 'maestria', 'opcion', 2, 1280, 1700, 'En el ajedrez de élite actual, ¿qué papel cumplen los motores en la preparación de aperturas?', '["Sirven para analizar líneas larguísimas de antemano","Están prohibidos en cualquier fase de preparación","Solo se pueden usar durante la partida, nunca antes","No influyen en cómo se prepara un profesional"]'::jsonb, null, 0, null, null, 'Se preparan variantes concretas hasta la jugada veinte o más, en casa y con el motor. Por eso en la élite hay partidas donde la primera jugada pensada de verdad llega pasada la jugada 20.', null, null),
  ('reg_legal_enroque_largo', 'reglas', 'opcion_tablero', 2, 1380, 1600, 'Juegan las blancas. Solo una de estas jugadas es legal: ¿cuál?', '["O-O-O","O-O","Cd5","Rf1"]'::jsonb, '4k3/ppp2ppp/b7/8/1b6/2N5/PPP2PPP/R3K2R w KQ - 0 12', 0, null, null, 'El alfil de a6 controla f1: el rey no puede pasar por ahí, así que O-O y Rf1 son ilegales. Cd5 tampoco: el caballo está clavado contra el rey por el alfil de b4. El enroque largo sí vale: el rey pasa por d1 y llega a c1, que no están atacadas (que la torre cruce b1 da igual).', null, null),
  ('reg_legal_al_paso_fila', 'reglas', 'opcion_tablero', 3, 1520, 2000, 'Las negras acaban de jugar …c7-c5. Juegan las blancas. Solo una de estas jugadas es legal: ¿cuál?', '["b6","bxc6","Ra6","Rb4"]'::jsonb, '1n5k/8/8/KPp4r/8/8/8/8 w - c6 0 40', 0, null, null, 'La trampa es bxc6 al paso: al capturar se van de la quinta fila los DOS peones (el blanco y el negro), y la torre de h5 queda dando jaque al rey de a5. Por eso es ilegal, aunque la captura al paso esté disponible. Ra6 lo controla el caballo de b8 y Rb4 el peón de c5. Queda b6, que no destapa nada.', null, null),
  ('reg_legal_jaque_doble', 'reglas', 'opcion_tablero', 3, 1470, 1500, 'El rey blanco recibe jaque del caballo de h3 y del alfil de c5 a la vez. Solo una de estas jugadas es legal: ¿cuál?', '["Rh1","gxh3","Te3","Rf1"]'::jsonb, '5rk1/ppp3pp/8/2b5/8/7n/6PP/4R1K1 w - - 0 25', 0, null, null, 'Contra un jaque doble no sirve capturar ni tapar: gxh3 deja el jaque del alfil y Te3 deja el del caballo. Solo el rey puede moverse, y no a f1, que la controla la torre de f8. Queda Rh1.', null, null),
  ('reg_legal_clavada_linea', 'reglas', 'opcion_tablero', 3, 1480, 1700, 'Juegan las blancas. Solo una de estas jugadas es legal: ¿cuál?', '["Te6","Tf4","Cf3","Rf1"]'::jsonb, '4r1k1/5ppp/8/8/1b2R3/7b/PP1N1P1P/4K3 w - - 0 30', 0, null, null, 'La torre de e4 está clavada por la de e8, pero una pieza clavada SÍ puede moverse a lo largo de la línea de la clavada: Te6 es legal. Tf4 la saca de la columna y destapa al rey. El caballo de d2 está clavado por el alfil de b4 y no tiene casilla en esa diagonal, y f1 la controla el alfil de h3.', null, null),
  ('reg_dos_caballos_sigue', 'reglas', 'opcion', 4, 1920, 1750, 'Quedan rey y dos caballos contra rey solo. Según el reglamento de la FIDE, ¿qué pasa con la partida?', '["Sigue: el mate no se fuerza, pero es posible","Tablas en el acto por material insuficiente","Tablas solo si el rey débil está en el centro","Gana el de los caballos si da mate en 50 jugadas"]'::jsonb, null, 0, null, null, 'La partida termina en tablas solo si NINGUNA serie de jugadas legales puede llevar al mate (Leyes, art. 5.2.2). Con dos caballos hay posiciones de mate —si el defensor se equivoca—, así que la partida sigue. Lo que no se puede es forzarlo: con buena defensa, es tablas por las 50 jugadas o por acuerdo.', null, null),
  ('fin_alfil_caballo_33', 'finales', 'opcion', 4, 1750, 1900, 'Rey, alfil y caballo contra rey solo, con la mejor defensa. ¿Alcanza la regla de las 50 jugadas para dar mate?', '["Sí: desde cualquier posición bastan 33 jugadas","No: en el peor caso hacen falta unas 60 jugadas","Solo si el rey débil ya está en una esquina","No: con buena defensa es tablas teórico"]'::jsonb, null, 0, null, null, 'Las bases de finales lo zanjaron: el mate más largo, desde la peor posición, es en 33 jugadas. Lo que confunde es la esquina: el mate se da en una esquina del color del alfil, y llevar al rey de la otra esquina a esa (con la maniobra en W del caballo) es lo que hay que saber hacer.', null, null),
  ('fin_dos_caballos_peon', 'finales', 'opcion', 5, 2150, 2150, 'Rey y dos caballos contra rey y un peón negro bloqueado lejos. ¿Por qué ESTE final a veces se gana y el de dos caballos contra rey solo no?', '["El peón le da jugadas al negro: ya no hay ahogado","Porque el peón negro se puede capturar y coronar","Porque con peón ya no hay material insuficiente","No es cierto: los dos finales son siempre tablas"]'::jsonb, null, 0, null, null, 'Con rey solo, el defensor se salva porque al acorralarlo aparece el ahogado. Con un peón que todavía puede mover, el negro tiene jugadas de sobra, no hay ahogado y un caballo puede ir a dar el mate mientras el otro sujeta el peón (la línea de Troitzky dice hasta dónde puede estar avanzado).', null, null),
  ('reg_legal_al_paso_jaque', 'reglas', 'opcion_tablero', 3, 1460, 2050, 'Las negras acaban de jugar …d7-d5, y ese peón le da jaque al rey blanco. Solo una de estas jugadas es legal: ¿cuál?', '["exd6","Rxd5","Re3","Rf4"]'::jsonb, '5r2/8/2p5/3pP3/4K3/8/5b2/k7 w - d6 0 50', 0, null, null, 'La captura al paso también sirve para salir del jaque: exd6 se come al peón que da jaque. Parece ilegal porque el peón blanco no «ataca» d5, pero la regla es la de siempre: justo después del avance doble, se captura como si hubiera avanzado una sola casilla. Rxd5 no, porque el peón de c6 lo defiende; e3 la controla el alfil de f2 y f4 la torre de f8.', null, null),
  ('reg_legal_enroque_torre_atacada', 'reglas', 'opcion_tablero', 3, 1440, 1700, 'Juegan las blancas. Solo una de estas jugadas es legal: ¿cuál?', '["O-O","O-O-O","Ad3","Re2"]'::jsonb, 'r3k2r/ppp2pp1/8/8/1b4b1/8/PPPB1PP1/R3K2R w KQkq - 0 14', 0, null, null, 'La torre de h1 está atacada por la de h8, y aun así se puede enrocar corto: la regla mira solo al rey (que no esté en jaque y que no pase ni llegue a una casilla atacada). El largo no, porque el rey pasaría por d1, que controla el alfil de g4. El alfil de d2 está clavado por el de b4, y e2 también la controla el de g4.', null, null),
  ('reg_no_ahoga_dama', 'reglas', 'opcion_tablero', 2, 1360, 1500, 'Dama y rey contra rey. Juegan las blancas. ¿Cuál de estas jugadas NO ahoga al rey negro?', '["Da7","Df7","De6","Rh6"]'::jsonb, '7k/8/6K1/8/8/8/Q7/8 w - - 0 1', 0, null, null, 'Df7 es el ahogado famoso, pero De6 también ahoga: la dama controla g8 desde lejos y el rey de g6 cubre g7 y h7. Rh6 deja al rey negro sin g8 (lo sigue viendo la dama desde a2) y tampoco tiene otra casilla. Da7 parece igual de encerradora, pero deja libre g8: el negro juega …Rg8 y después viene Dg7 mate.', null, null),
  ('reg_75_jugadas', 'reglas', 'opcion', 3, 1550, 1850, 'Se juegan 75 jugadas seguidas de cada bando sin ninguna captura ni movimiento de peón, y la última no es mate. Según las Leyes de la FIDE, ¿qué pasa?', '["El árbitro declara tablas aunque nadie lo pida","Nada: solo son tablas si un jugador las reclama","Tablas, pero solo si quedan menos de 7 piezas","Gana quien tenga más material en el tablero"]'::jsonb, null, 0, null, null, 'Con 50 jugadas, las tablas hay que reclamarlas; con 75 son automáticas (Leyes, art. 9.6.2), igual que la quíntuple repetición. La confusión típica es aplicar a las 75 lo que vale para las 50.', null, null),
  ('mat_lx_0G3dE_op', 'material', 'opcion_tablero', 1, 805, 965, 'Las negras acaban de jugar …Tc2. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Dxe4","Dxf7+","Txe4","De6"]'::jsonb, '3r1k2/1p3pp1/p6p/3N1Q2/4nP2/P5qP/1Pr3P1/3RR1K1 w - - 4 32', 0, null, null, 'Hay algo sin defender, y hay que verlo antes que el rival. La línea: 32.Dxe4 Txg2+ 33.Dxg2. Las otras tientan, pero fallan: Dxf7+? se contesta con 32…Rxf7 y las blancas reciben mate; Txe4? se contesta con 32…Dxg2# y las blancas reciben mate; De6? se contesta con 32…Dxg2# y las blancas reciben mate.', '0G3dE', 1515),
  ('mat_lx_1Aqtu_op', 'material', 'opcion_tablero', 1, 760, 922, 'Las negras acaban de jugar …Db6. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Cxc4","Dxc4","Cxc6","Cxf7"]'::jsonb, 'r1b2rk1/pp3ppp/1qpb4/3pN3/2nP1BPP/8/PPP1QPB1/1K1R3R w - - 3 16', 0, null, null, 'Es un ataque a la descubierta: al moverse una pieza, se destapa otra. La línea: 16.Cxc4 dxc4 17.Axd6. Las otras tientan, pero fallan: Dxc4? se contesta con 16…Axe5 y las negras quedan mejor; Cxc6? se contesta con 16…Dxb2# y las blancas reciben mate; Cxf7? se contesta con 16…Dxb2# y las blancas reciben mate.', '1Aqtu', 1472),
  ('mat_lx_1IhQd', 'material', 'jugada', 1, 548, 928, 'Las negras acaban de jugar …Axe2. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'r3k3/3q1pb1/p1pp1p2/2p1p3/4P2N/P2P2Q1/1PP1bP2/R3K3 w Qq - 0 18', null, '{"from":"g3","to":"g7"}'::jsonb, null, 'Hay una jugada intermedia: antes de lo obvio, algo más fuerte. La línea: 18.Dxg7 O-O-O 19.Rxe2.', '1IhQd', 1328),
  ('mat_lx_1NHsB_op', 'material', 'opcion_tablero', 1, 673, 833, 'Las negras acaban de jugar …Ag4. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Axf6","Axg4","Axd5","Ac3"]'::jsonb, 'r3r1k1/1p3ppp/pPp2n2/3p2q1/1P4b1/P3PB2/1B3PP1/R2Q1RK1 w - - 2 19', 0, null, null, 'Se captura al defensor y lo que defendía queda colgado. La línea: 19.Axf6 Dxf6 20.Axg4. Las otras tientan, pero fallan: Axg4? se contesta con 19…Cxg4 y las negras quedan mejor; Axd5? se contesta con 19…Cxd5 y las negras quedan mejor; Ac3? se contesta con 19…Axf3 y las negras quedan mejor.', '1NHsB', 1383),
  ('mat_lx_1a4Su', 'material', 'jugada', 1, 565, 945, 'Las negras acaban de jugar …c5. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'r6r/4kp1p/p2ppqpQ/2pp2N1/3P4/4P3/PPP1K1PP/7R w - - 0 18', null, '{"from":"h1","to":"f1"}'::jsonb, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 18.Tf1 Dxf1+ 19.Rxf1.', '1a4Su', 1345),
  ('mat_lx_1cZ0z_op', 'material', 'opcion_tablero', 1, 840, 1007, 'Las negras acaban de jugar …h4. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Te4","Txe5","Ce4","Dxb5"]'::jsonb, 'r4rk1/2pn1pp1/p7/1pbPpP2/6qp/1QP3N1/P2B2PP/4RR1K w - - 0 21', 0, null, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 21.Te4 Cf6 22.Txg4. Las otras tientan, pero fallan: Txe5? se contesta con 21…Cxe5 y las negras quedan mejor; Ce4? se contesta con 21…Ae7 y la ventaja se esfuma; Dxb5? se contesta con 21…axb5 y las negras quedan mejor.', '1cZ0z', 1557),
  ('mat_lx_2QcC0', 'material', 'jugada', 1, 670, 1053, 'Las negras acaban de jugar …Txe5. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, '6k1/5q2/1pp4p/3br1p1/2n2p2/P1QR4/2P1BFP1/6K1 w - - 0 31', null, '{"from":"d3","to":"d5"}'::jsonb, null, 'Es un ataque a la descubierta: al moverse una pieza, se destapa otra. La línea: 31.Txd5 Txd5 32.Axc4.', '2QcC0', 1453),
  ('mat_lx_2Td3q', 'material', 'jugada', 1, 635, 1015, 'Las negras acaban de jugar …Ce4. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'r1b2r1k/2q3pp/p1p5/1pb2pB1/4n3/3BP2P/PPQ1NP2/1K1R3R w - - 4 19', null, '{"from":"d3","to":"e4"}'::jsonb, null, 'Se captura al defensor y lo que defendía queda colgado. La línea: 19.Axe4 fxe4 20.Dxc5.', '2Td3q', 1415),
  ('mat_lx_01sqg', 'material', 'jugada', 1, 800, 1190, 'Las negras acaban de jugar …Cd5. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, '4rr1k/pp4pp/2p1B3/2bnpP1q/8/2NP1R2/PPPB2QP/4K3 w - - 7 21', null, '{"from":"f3","to":"h3"}'::jsonb, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 21.Th3 Af2+ 22.Rxf2 Dxh3 23.Dxh3.', '01sqg', 1590),
  ('mat_lx_07CGX', 'material', 'jugada', 1, 866, 1246, 'Las negras acaban de jugar …Rb6. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, '2r5/3K3p/1k1P2p1/R4p2/1P6/2p3P1/7r/8 w - - 4 37', null, '{"from":"d7","to":"c8"}'::jsonb, null, 'Hay algo sin defender, y hay que verlo antes que el rival. La línea: 37.Rxc8 c2 38.Tc5 c1=A 39.Txc1.', '07CGX', 1646),
  ('mat_lx_0ZgWo', 'material', 'jugada', 1, 1040, 1145, 'Las negras acaban de jugar …Re5. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, '8/8/8/3pk1p1/8/4K1P1/8/1B2n3 w - - 14 51', null, '{"from":"e3","to":"f2"}'::jsonb, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 51.Rf2 Cf3 52.Rxf3.', '0ZgWo', 1545),
  ('mat_lx_0c1Kn', 'material', 'jugada', 1, 989, 1369, 'Las negras acaban de jugar …b5. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'rnbq3r/2k1nBb1/p2p4/1ppP2B1/Q1N1P3/2P5/PP5p/R4R1K w - b6 0 17', null, '{"from":"a4","to":"a5"}'::jsonb, null, 'Es una desviación: se aleja al defensor de lo que defendía. La línea: 17.Da5+ Rb7 18.Dxd8 Txd8 19.Axe7.', '0c1Kn', 1769),
  ('mat_lx_1jxRo_op', 'material', 'opcion_tablero', 2, 1190, 1387, 'Las negras acaban de jugar …f6. Juegan las blancas y están en apuros. Solo una de estas jugadas salva la partida: ¿cuál?', '["Axd5+","Cxc6","Axf6","Cxg6"]'::jsonb, 'r1b2rk1/pp2p2p/2n2pp1/q1pnN1B1/8/3P2P1/PQ1N1PBP/4K2R w K - 0 15', 0, null, null, 'Todo gira en torno a una clavada: la pieza clavada no puede defender. La línea: 15.Axd5+ Rg7 16.Cxc6. Las otras tientan, pero fallan: Cxc6? se contesta con 15…bxc6 y las negras quedan mejor; Axf6? se contesta con 15…Cxf6 y las negras quedan mejor; Cxg6? se contesta con 15…Cdb4 y las negras quedan mejor.', '1jxRo', 1937),
  ('mat_lx_3DeOk_op', 'material', 'opcion_tablero', 3, 1540, 1375, 'Las negras acaban de jugar …Cgxe5. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Axf7+","Cxf7","Dxe5","Ae6"]'::jsonb, 'r1bqr1k1/pppnppbp/6p1/4n1N1/2B5/2N5/PPP1QPPP/R1B2RK1 w - - 0 11', 0, null, null, 'Es un tenedor: una pieza ataca dos objetivos a la vez. La línea: 11.Axf7+ Cxf7 12.Ce6 Cf8 13.Cxd8. Las otras tientan, pero fallan: Cxf7? se contesta con 11…Cxf7 y las negras quedan mejor; Dxe5? se contesta con 11…Cxe5 y las negras quedan mejor; Ae6? se contesta con 11…Cc5 y la ventaja se esfuma.', '3DeOk', 1925),
  ('mat_lx_04crN', 'material', 'jugada', 2, 1138, 1518, 'Las negras acaban de jugar …Dxe3+. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'r4rk1/pb3p1p/1p2p1p1/3p1P2/6P1/1P1Bq2P/PBPK2Q1/5R2 w - - 0 23', null, '{"from":"d2","to":"e3"}'::jsonb, null, 'Hay algo sin defender, y hay que verlo antes que el rival. La línea: 23.Rxe3 d4+ 24.Rf2 Axg2 25.Rxg2.', '04crN', 1918),
  ('mat_lx_0Ryjs_op', 'material', 'opcion_tablero', 3, 1430, 1603, 'Las negras acaban de jugar …c6. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Cxd4","Axc6+","Axf7+","Ce5"]'::jsonb, 'r2qkbnr/4pppp/p1pp4/1p1B4/3nP1b1/3P1N2/PPP2PPP/RNBQK2R w KQkq - 0 8', 0, null, null, 'Es un ataque a la descubierta: al moverse una pieza, se destapa otra. La línea: 8.Cxd4 cxd5 9.Dxg4. Las otras tientan, pero fallan: Axc6+? se contesta con 8…Cxc6 y las negras quedan mejor; Axf7+? se contesta con 8…Rxf7 y las negras quedan mejor; Ce5? se contesta con 8…dxe5 y las negras quedan mejor.', '0Ryjs', 2153),
  ('mat_lx_2BEXB', 'material', 'jugada', 2, 1350, 1457, 'Las negras acaban de jugar …Dxg4. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'rn3rk1/1p4bp/p3N1p1/2pP1p2/2P3q1/3Q2P1/PP5P/R4RK1 w - - 0 20', null, '{"from":"f1","to":"f4"}'::jsonb, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 20.Tf4 Dh5 21.Th4 Dxh4 22.gxh4.', '2BEXB', 1857),
  ('mat_lx_2Eocm', 'material', 'jugada', 1, 1080, 1494, 'Las negras acaban de jugar …gxf6. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'r4n1k/1b5p/1p3p2/p7/n7/PK3N2/2PR2PP/5R2 w - - 0 33', null, '{"from":"b3","to":"a4"}'::jsonb, null, 'Hay algo sin defender, y hay que verlo antes que el rival. La línea: 33.Rxa4 b5+ 34.Rb3.', '2Eocm', 1894),
  ('mat_lx_2YUQN', 'material', 'jugada', 1, 1090, 1472, 'Las negras acaban de jugar …exd4. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'r3k1nr/ppp2ppp/8/2b2b2/3pN3/3BB3/PPP2PPP/R3K2R w KQkq - 0 10', null, '{"from":"e4","to":"c5"}'::jsonb, null, 'Hay una jugada intermedia: antes de lo obvio, algo más fuerte. La línea: 10.Cxc5 Axd3 11.Axd4.', '2YUQN', 1872),
  ('mat_lx_0IObO_op', 'material', 'opcion_tablero', 4, 1720, 1764, 'Las negras acaban de jugar …Dg4. Juegan las blancas y están en apuros. Solo una de estas jugadas salva la partida: ¿cuál?', '["Ag3","cxb5","g3","Ag5"]'::jsonb, '5rk1/1pp2pp1/1p1p3p/1r2p2n/RPP1P1qB/3P1N1b/5PP1/3Q1RK1 w - - 1 19', 0, null, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 19.Ag3 Cxg3 20.fxg3 Txb4 21.Txb4. Las otras tientan, pero fallan: cxb5? se contesta con 19…Dxg2# y las blancas reciben mate; g3? se contesta con 19…Axf1 y las negras quedan mejor; Ag5? se contesta con 19…Dxg2# y las blancas reciben mate.', '0IObO', 2314),
  ('mat_lx_0LZhu_op', 'material', 'opcion_tablero', 3, 1610, 1888, 'Las negras acaban de jugar …Txg5. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Txe6","Axg5","cxd5","Dxf5"]'::jsonb, '4r1k1/pp2q1pp/2nbp3/3p1pr1/2PP4/7P/PPQBRPP1/4R1K1 w - - 0 21', 0, null, null, 'Se captura al defensor y lo que defendía queda colgado. La línea: 21.Txe6 Dxe6 22.Txe6 Txe6 23.cxd5. Las otras tientan, pero fallan: Axg5? se contesta con 21…Dxg5 y las negras quedan mejor; cxd5? se contesta con 21…Cxd4 y las negras quedan mejor; Dxf5? se contesta con 21…Txf5 y las negras quedan mejor.', '0LZhu', 2438),
  ('mat_lx_0PdD5', 'material', 'jugada', 2, 1390, 1811, 'Las negras acaban de jugar …Tae8. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, '4rrk1/p1p2ppp/1p1p4/2nP1PPq/2P2R2/2P3Q1/P5BP/4R1K1 w - - 5 24', null, '{"from":"e1","to":"e8"}'::jsonb, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 24.Txe8 Txe8 25.Af3 Te3 26.Axh5.', '0PdD5', 2211),
